package com.acxelin.hisaabsaathi.core

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Runs every prompt in corpus.jsonl (several hundred, six languages) through the same
 * decision the app makes and checks the result. A report goes to build/corpus-report.txt.
 * The corpus is generated by tools/make_corpus.py.
 */
class CorpusTest {
    private fun expected(o: JsonObject): String = when (o["kind"]!!.jsonPrimitive.content) {
        "entries" -> o["entries"]!!.jsonArray.joinToString("; ") { e ->
            val j = e.jsonObject
            fun n(k: String) = j[k]?.jsonPrimitive?.content
            listOfNotNull(n("type"), n("amount"), n("hours")?.let { "h$it" }, n("pieces")?.let { "p$it" }, n("rate")?.let { "r$it" }, n("category"), n("dayOffset")?.let { "d$it" }).joinToString(" ")
        }
        "query" -> "ASK ${o["period"]!!.jsonPrimitive.content} ${o["topic"]!!.jsonPrimitive.content}"
        "chat" -> "TALK ${o["chat"]!!.jsonPrimitive.content}"
        else -> "UNKNOWN"
    }

    private fun num(v: Double) = if (v == Math.floor(v)) v.toLong().toString() else v.toString()

    private fun actual(text: String): String = when (val u = Understand.of(text)) {
        is Understood.Entries -> u.extraction.entries.joinToString("; ") { d ->
            listOfNotNull(
                d.type.name, Money.format(d.amountPaise), d.hours?.let { "h${num(it)}" }, d.pieces?.let { "p$it" },
                d.ratePaise?.let { "r${Money.format(it)}" }, d.category?.name, d.dayOffset.takeIf { it != 0 }?.let { "d$it" },
            ).joinToString(" ")
        }
        is Understood.Ask -> "ASK ${u.query.period} ${u.query.topic}"
        is Understood.Talk -> "TALK ${u.chat}"
        is Understood.Unknown -> "UNKNOWN"
    }

    @Test fun everyPromptIsUnderstood() {
        val lines = corpus().map { it.toString() }
        val total = HashMap<String, Int>(); val ok = HashMap<String, Int>()
        val failures = ArrayList<String>()
        for (line in lines) {
            val o = Json.parseToJsonElement(line).jsonObject
            val lang = o["lang"]!!.jsonPrimitive.content
            val text = o["text"]!!.jsonPrimitive.content
            val want = expected(o); val got = actual(text)
            total.merge(lang, 1, Int::plus)
            if (want == got) ok.merge(lang, 1, Int::plus) else failures += "[$lang] $text\n    want: $want\n    got:  $got"
        }
        val report = buildString {
            appendLine("Corpus: ${lines.size} prompts, ${lines.size - failures.size} correct")
            for (lang in total.keys.sorted()) appendLine("  $lang: ${ok[lang] ?: 0}/${total[lang]}")
            failures.forEach { appendLine(it) }
        }
        File("build").mkdirs()
        File("build/corpus-report.txt").writeText(report)
        assertTrue("Understood ${lines.size - failures.size} of ${lines.size}; see core/build/corpus-report.txt", failures.isEmpty())
    }

    private fun corpus() = javaClass.getResource("/corpus.jsonl")!!.readText().lines().filter { it.isNotBlank() }
        .map { Json.parseToJsonElement(it).jsonObject }

    /** Writes the exact prompts the app would send, for tools/eval_slm.py to run through a model. */
    @Test fun writePromptsForModelEvaluation() {
        val names = mapOf("hi-Latn" to "Hindi") + Lang.entries.associate { it.code to it.englishName }
        val out = corpus().map { o ->
            val text = o["text"]!!.jsonPrimitive.content
            val kind = o["kind"]!!.jsonPrimitive.content
            val prompt = if (kind == "entries") Slm.prompt(text) else Slm.chatPrompt(text, names.getValue(o["lang"]!!.jsonPrimitive.content))
            kotlinx.serialization.json.buildJsonObject {
                put("lang", o["lang"]!!); put("kind", o["kind"]!!); put("text", o["text"]!!)
                put("prompt", kotlinx.serialization.json.JsonPrimitive(prompt ?: ""))
            }.toString()
        }
        File("build").mkdirs()
        File("build/slm_prompts.jsonl").writeText(out.joinToString("\n"))
    }

    /**
     * Scores recorded model answers (src/test/resources/slm_*.jsonl, made by tools/eval_slm.py)
     * with the app's own validator. Informational: it writes build/slm-report.txt.
     */
    @Test fun scoreRecordedModelAnswers() {
        val want = corpus().filter { it["kind"]!!.jsonPrimitive.content == "entries" }.associate { it["text"]!!.jsonPrimitive.content to expected(it) }
        val report = StringBuilder()
        for (tag in listOf("qwen05", "qwen15")) {
            val res = javaClass.getResource("/slm_$tag.jsonl") ?: continue
            val rows = res.readText().lines().filter { it.isNotBlank() }.map { Json.parseToJsonElement(it).jsonObject }
            var n = 0; var accepted = 0; var right = 0; var wrongAccepted = 0
            val byLang = HashMap<String, IntArray>()
            val samples = ArrayList<String>()
            for (r in rows.filter { it["task"]!!.jsonPrimitive.content == "extract" }) {
                val text = r["text"]!!.jsonPrimitive.content
                val drafts = Slm.parse(r["output"]!!.jsonPrimitive.content, text, RuleBasedExtractor.extract(text).entries.firstOrNull()?.dayOffset ?: 0)
                val got = drafts?.joinToString("; ") { d ->
                    listOfNotNull(d.type.name, Money.format(d.amountPaise), d.hours?.let { "h${num(it)}" }, d.pieces?.let { "p$it" },
                        d.ratePaise?.let { "r${Money.format(it)}" }, d.category?.name, d.dayOffset.takeIf { it != 0 }?.let { "d$it" }).joinToString(" ")
                }
                val counts = byLang.getOrPut(r["lang"]!!.jsonPrimitive.content) { IntArray(3) }
                n++; counts[0]++
                if (got != null) { accepted++; counts[1]++ }
                if (got == want[text]) { right++; counts[2]++ } else if (got != null) {
                    wrongAccepted++
                    if (samples.size < 12) samples += "  $text\n      want ${want[text]}\n      got  $got"
                }
            }
            report.appendLine("$tag: $n entry prompts; answer usable $accepted; fully correct $right; usable but wrong $wrongAccepted")
            for ((lang, c) in byLang.toSortedMap()) report.appendLine("  $lang: ${c[2]}/${c[0]} correct, ${c[1]} usable")
            samples.forEach { report.appendLine(it) }
        }
        File("build").mkdirs()
        File("build/slm-report.txt").writeText(report.toString())
    }
}
